records=[]
def batch(group, text):
 for line in text.strip().splitlines():
  if not line.strip(): continue
  parts=[x.strip() for x in line.split('|||')]
  assert len(parts)==11,(len(parts),line[:80])
  title,principle,math,inputs,build,run,verify,negative,done,src,branch=parts
  n=376+len(records)
  record=dict(id=f'AS{n}',group=group,title=title,principle=principle,math=math,
   inputs=inputs+' Freeze the supplied sample and units before estimating the target; missing covariance or calibration inputs permit only a labeled synthetic exercise, never an observed significance.',
   steps=[build,run,verify,
    'Produce a table of the named estimand, numerical residuals, and uncertainty or rigorous enclosure on exactly the stated domain. Retain failed cells and distinguish a data limitation from a failure of the named implication.'],
   checks=[negative,'Repeat the decisive calculation with an independent implementation or analytic limiting case. State the tolerance before comparing results and retain both outputs if they disagree.'],
   completion=done+' This completes only the named implication; it does not establish full same-action gravity closure.',
   sources=[S[x] for x in src.split(',')],branch=branch,depends_on=[],priority='P1',kind='computation')
  records.append(record)
